package upwind.detections.t1611.container_escape_runtime_evidence

# Container escape consummation signals:
#   1. Namespace-transition syscalls (setns, unshare, pivot_root) where the
#      target namespace differs from the source, observed inside a container.
#   2. File writes from inside a container to a host-bound mount or to a
#      container runtime socket.
#
# Authored against the Upwind Explorer Rego policy surface. Field paths
# follow public Explorer documentation patterns; verify against the actual
# tenant schema before deploying.

default deny := false

namespace_transition_syscalls := {"setns", "unshare", "pivot_root"}

runtime_sockets := {
  "/var/run/docker.sock",
  "/var/run/containerd/containerd.sock",
  "/run/crio/crio.sock",
}

# Branch 1: namespace traversal
deny if {
  input.event.kind == "syscall"
  input.event.syscall in namespace_transition_syscalls
  input.process.container.id != ""
  input.process.namespaces.target != input.process.namespaces.source
}

# Branch 2: file write from inside a container into host-bound storage
deny if {
  input.event.kind == "file_write"
  input.process.container.id != ""
  host_bound_target
}

host_bound_target if {
  startswith(input.file.path, "/host")
}

host_bound_target if {
  input.file.path in runtime_sockets
}

host_bound_target if {
  input.file.host_mount == true
}

finding := {
  "severity": "critical",
  "technique": "T1611",
  "cluster": input.cluster.name,
  "namespace": input.workload.namespace,
  "workload": input.workload.name,
  "image": input.container.image,
  "process": input.process.cmdline,
  "file": input.file.path,
  "syscall": input.event.syscall,
} if {
  deny
}
